import * as React from "react"
import { PageProps, graphql } from "gatsby"
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import Layout from "../components/layout"
import images from "../images";
import { useTranslation } from "gatsby-plugin-react-i18next";
import ContactForm from "../components/contactForm";

const userData: UserProfile = data;

const ContactPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout 
      data={userData}
      iconAndTextColor="DeepSea"
      footerLogoFill="fill-Tofu"
      bgColorPage="Trooper"
      bgImage={images.contactVideo.src}
      footerBackground="linear-gradient(to top, rgba(32,47,47,1) 0%,rgba(32,47,47,0) 100%)"
    >
        <section className={styles.section}>
            <h1 className="head-3 uppercase">{t("contact.title")}</h1>
            <div className="mt-6 sm:mt-0">
                <ContactForm />
            </div>
        </section>
    </Layout>
  )
}

export default ContactPage

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  section: "flex flex-col sm:flex-row justify-between mt-24 mb-32 sm:mb-0 mx-8 sm:mx-16",
}